-- Alternative method using TouchEnabled
local UserInputService = game:GetService("UserInputService")

local function isMobileDevice()
    -- Method 1: Check TouchEnabled
    if UserInputService.TouchEnabled then
        return true
    end
    
    -- Method 2: Check Platform
    local platform = tostring(UserInputService:GetPlatform())
    if platform:find("Android") or platform:find("IOS") or platform:find("Mobile") then
        return true
    end
    
    return false
end

